-- ============================================================================
-- V1__init_schema.sql
-- MSME Inventory + GST Billing Platform - initial schema (MVP)
--
-- Design notes for reviewers:
--   * Multi-tenancy: shared schema, row-level isolation via tenant_id on
--     every table. Enforce tenant scoping in the application layer (every
--     query/repository must filter by tenant_id); Postgres Row Level
--     Security can be layered on top later without a schema change.
--   * Primary keys are UUIDs, generated by the application (not the
--     database) before insert - so IDs are safe to expose in URLs/APIs,
--     don't leak row counts or sequencing across tenants, and are known
--     to the app before the row is persisted (useful for building related
--     rows in the same transaction without a round trip for the id).
--   * Every product always has >= 1 row in product_variants. Products with
--     no real variation (e.g. a single loose SKU) still get exactly one
--     variant row. Stock, pricing, SKU, HSN/GST all live on the variant,
--     never on the product - this keeps the schema generic across product
--     types (apparel with size/color, beverages with volume, or plain
--     goods with no attributes at all) without special-casing anywhere
--     else in the system.
--   * product_variants.attributes is JSONB rather than a normalized EAV
--     model. At MSME scale this is simpler to query and map via JPA, and
--     a GIN index keeps attribute lookups fast if ever needed.
--   * stock_ledger is an append-only audit trail of every stock movement.
--     product_variants.current_stock is a denormalized cache of the
--     running balance, updated in the same transaction as each ledger
--     insert, so read-heavy stock checks don't need to SUM the ledger.
--   * GST: CGST+SGST vs IGST is determined by comparing the tenant's
--     state_code to the invoice's place_of_supply_state_code (application
--     logic), so both amounts are stored per invoice/line rather than a
--     single tax amount. invoice_number_sequences gives atomic, gapless,
--     sequential numbering per tenant per financial year, which is a legal
--     requirement for GST invoices in India.
--   * created_at/updated_at are maintained by a trigger so application
--     code can never forget to set them.
-- ============================================================================

CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ----------------------------------------------------------------------------
-- tenants: one row per MSME business using the platform
-- ----------------------------------------------------------------------------
CREATE TABLE tenants (
    id                  UUID PRIMARY KEY,
    business_name       TEXT NOT NULL,
    gstin               VARCHAR(15),
    pan                 VARCHAR(10),
    state_code          CHAR(2) NOT NULL,           -- GST state code of the business, e.g. '27' = Maharashtra
    address_line1       TEXT,
    address_line2       TEXT,
    city                TEXT,
    pincode             VARCHAR(10),
    email               TEXT NOT NULL,
    phone               VARCHAR(15),
    subscription_plan   VARCHAR(30) NOT NULL DEFAULT 'FREE',
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_tenants_email UNIQUE (email),
    CONSTRAINT chk_tenants_gstin_format CHECK (
        gstin IS NULL OR gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$'
    )
);

CREATE TRIGGER trg_tenants_updated_at
    BEFORE UPDATE ON tenants
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ----------------------------------------------------------------------------
-- users: staff/owner accounts, scoped to a tenant
-- ----------------------------------------------------------------------------
CREATE TABLE users (
    id              UUID PRIMARY KEY,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name            TEXT NOT NULL,
    email           TEXT NOT NULL,
    password_hash   TEXT NOT NULL,
    role            VARCHAR(20) NOT NULL DEFAULT 'STAFF' CHECK (role IN ('OWNER', 'STAFF')),
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    last_login_at   TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_users_tenant_email UNIQUE (tenant_id, email)
);

CREATE INDEX idx_users_tenant_id ON users(tenant_id);

CREATE TRIGGER trg_users_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ----------------------------------------------------------------------------
-- categories: tenant-defined product categories (optional hierarchy)
-- ----------------------------------------------------------------------------
CREATE TABLE categories (
    id                  UUID PRIMARY KEY,
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name                TEXT NOT NULL,
    parent_category_id  UUID REFERENCES categories(id) ON DELETE SET NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_categories_tenant_name UNIQUE (tenant_id, name)
);

CREATE INDEX idx_categories_tenant_id ON categories(tenant_id);

CREATE TRIGGER trg_categories_updated_at
    BEFORE UPDATE ON categories
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ----------------------------------------------------------------------------
-- products: the "parent" item. No stock/price/SKU here - see product_variants.
-- ----------------------------------------------------------------------------
CREATE TABLE products (
    id                  UUID PRIMARY KEY,
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    category_id         UUID REFERENCES categories(id) ON DELETE SET NULL,
    name                TEXT NOT NULL,
    brand               TEXT,
    description         TEXT,
    default_hsn_code    VARCHAR(8),
    default_gst_rate    NUMERIC(5,2) NOT NULL DEFAULT 0,
    default_uom         VARCHAR(20) NOT NULL DEFAULT 'PCS',
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_products_gst_rate CHECK (default_gst_rate >= 0 AND default_gst_rate <= 100)
);

CREATE INDEX idx_products_tenant_id ON products(tenant_id);
CREATE INDEX idx_products_category_id ON products(category_id);

CREATE TRIGGER trg_products_updated_at
    BEFORE UPDATE ON products
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ----------------------------------------------------------------------------
-- product_variants: the actual sellable/stockable unit.
-- Every product has at least one variant, even if attributes = '{}'.
-- ----------------------------------------------------------------------------
CREATE TABLE product_variants (
    id                  UUID PRIMARY KEY,
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    product_id          UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
    sku                 VARCHAR(100) NOT NULL,
    barcode             VARCHAR(100),
    attributes          JSONB NOT NULL DEFAULT '{}'::jsonb,   -- e.g. {"size":"M","color":"Red"} or {"volume":"500ml"}
    purchase_price      NUMERIC(12,2) NOT NULL DEFAULT 0,
    selling_price       NUMERIC(12,2) NOT NULL DEFAULT 0,
    hsn_code            VARCHAR(8),      -- overrides products.default_hsn_code when set
    gst_rate            NUMERIC(5,2),    -- overrides products.default_gst_rate when set
    uom                 VARCHAR(20),     -- overrides products.default_uom when set
    reorder_threshold   NUMERIC(12,3) NOT NULL DEFAULT 0,
    current_stock       NUMERIC(14,3) NOT NULL DEFAULT 0,   -- denormalized cache, kept in sync with stock_ledger
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_product_variants_tenant_sku UNIQUE (tenant_id, sku),
    CONSTRAINT chk_product_variants_prices CHECK (purchase_price >= 0 AND selling_price >= 0),
    CONSTRAINT chk_product_variants_gst_rate CHECK (gst_rate IS NULL OR (gst_rate >= 0 AND gst_rate <= 100))
);

CREATE INDEX idx_product_variants_tenant_id ON product_variants(tenant_id);
CREATE INDEX idx_product_variants_product_id ON product_variants(product_id);
CREATE INDEX idx_product_variants_attributes ON product_variants USING GIN (attributes);
CREATE UNIQUE INDEX uq_product_variants_tenant_barcode
    ON product_variants(tenant_id, barcode) WHERE barcode IS NOT NULL;

CREATE TRIGGER trg_product_variants_updated_at
    BEFORE UPDATE ON product_variants
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ----------------------------------------------------------------------------
-- vendors: suppliers a tenant buys from
-- ----------------------------------------------------------------------------
CREATE TABLE vendors (
    id              UUID PRIMARY KEY,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name            TEXT NOT NULL,
    gstin           VARCHAR(15),
    state_code      CHAR(2),
    contact_person  TEXT,
    phone           VARCHAR(15),
    email           TEXT,
    address_line1   TEXT,
    address_line2   TEXT,
    city            TEXT,
    pincode         VARCHAR(10),
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_vendors_tenant_id ON vendors(tenant_id);

CREATE TRIGGER trg_vendors_updated_at
    BEFORE UPDATE ON vendors
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ----------------------------------------------------------------------------
-- customers: buyers a tenant sells to
-- ----------------------------------------------------------------------------
CREATE TABLE customers (
    id              UUID PRIMARY KEY,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    name            TEXT NOT NULL,
    gstin           VARCHAR(15),
    state_code      CHAR(2),
    contact_person  TEXT,
    phone           VARCHAR(15),
    email           TEXT,
    address_line1   TEXT,
    address_line2   TEXT,
    city            TEXT,
    pincode         VARCHAR(10),
    is_active       BOOLEAN NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_customers_tenant_id ON customers(tenant_id);

CREATE TRIGGER trg_customers_updated_at
    BEFORE UPDATE ON customers
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ----------------------------------------------------------------------------
-- purchase_entries / purchase_line_items: stock-in via purchases
-- ----------------------------------------------------------------------------
CREATE TABLE purchase_entries (
    id                  UUID PRIMARY KEY,
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    vendor_id           UUID NOT NULL REFERENCES vendors(id),
    reference_number    TEXT,
    purchase_date       DATE NOT NULL,
    subtotal            NUMERIC(14,2) NOT NULL DEFAULT 0,
    total_tax           NUMERIC(14,2) NOT NULL DEFAULT 0,
    total_amount        NUMERIC(14,2) NOT NULL DEFAULT 0,
    created_by          UUID REFERENCES users(id),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_purchase_entries_tenant_id ON purchase_entries(tenant_id);
CREATE INDEX idx_purchase_entries_vendor_id ON purchase_entries(vendor_id);

CREATE TRIGGER trg_purchase_entries_updated_at
    BEFORE UPDATE ON purchase_entries
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE purchase_line_items (
    id                  UUID PRIMARY KEY,
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    purchase_entry_id   UUID NOT NULL REFERENCES purchase_entries(id) ON DELETE CASCADE,
    variant_id          UUID NOT NULL REFERENCES product_variants(id),
    quantity            NUMERIC(12,3) NOT NULL CHECK (quantity > 0),
    unit_price          NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0),
    gst_rate            NUMERIC(5,2) NOT NULL DEFAULT 0,
    line_total          NUMERIC(14,2) NOT NULL,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_purchase_line_items_tenant_id ON purchase_line_items(tenant_id);
CREATE INDEX idx_purchase_line_items_purchase_entry_id ON purchase_line_items(purchase_entry_id);
CREATE INDEX idx_purchase_line_items_variant_id ON purchase_line_items(variant_id);

-- ----------------------------------------------------------------------------
-- invoice_number_sequences: atomic, gapless, sequential numbering per tenant
-- per financial year - required for GST-compliant invoices.
-- Application must SELECT ... FOR UPDATE this row when issuing the next
-- invoice number, then UPDATE last_number in the same transaction.
-- ----------------------------------------------------------------------------
CREATE TABLE invoice_number_sequences (
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    financial_year  VARCHAR(7) NOT NULL,   -- e.g. '2025-26'
    last_number     BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (tenant_id, financial_year),
    CONSTRAINT chk_invoice_number_sequences_fy_format CHECK (financial_year ~ '^[0-9]{4}-[0-9]{2}$')
);

-- ----------------------------------------------------------------------------
-- invoices / invoice_line_items: stock-out via sales, GST-compliant
-- ----------------------------------------------------------------------------
CREATE TABLE invoices (
    id                          UUID PRIMARY KEY,
    tenant_id                   UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    customer_id                 UUID NOT NULL REFERENCES customers(id),
    financial_year              VARCHAR(7) NOT NULL,
    invoice_number              BIGINT NOT NULL,          -- sequential per tenant per FY
    invoice_display_number      VARCHAR(50) NOT NULL,     -- formatted, e.g. INV/2025-26/000123
    invoice_date                DATE NOT NULL,
    place_of_supply_state_code  CHAR(2) NOT NULL,
    subtotal                    NUMERIC(14,2) NOT NULL DEFAULT 0,
    cgst_amount                 NUMERIC(14,2) NOT NULL DEFAULT 0,
    sgst_amount                 NUMERIC(14,2) NOT NULL DEFAULT 0,
    igst_amount                 NUMERIC(14,2) NOT NULL DEFAULT 0,
    total_amount                NUMERIC(14,2) NOT NULL DEFAULT 0,
    status                      VARCHAR(20) NOT NULL DEFAULT 'FINAL' CHECK (status IN ('DRAFT', 'FINAL', 'CANCELLED')),
    created_by                  UUID REFERENCES users(id),
    created_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_invoices_tenant_fy_number UNIQUE (tenant_id, financial_year, invoice_number),
    CONSTRAINT uq_invoices_tenant_display_number UNIQUE (tenant_id, invoice_display_number)
);

CREATE INDEX idx_invoices_tenant_id ON invoices(tenant_id);
CREATE INDEX idx_invoices_customer_id ON invoices(customer_id);
CREATE INDEX idx_invoices_invoice_date ON invoices(tenant_id, invoice_date);

CREATE TRIGGER trg_invoices_updated_at
    BEFORE UPDATE ON invoices
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE invoice_line_items (
    id              UUID PRIMARY KEY,
    tenant_id       UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    invoice_id      UUID NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
    variant_id      UUID NOT NULL REFERENCES product_variants(id),
    quantity        NUMERIC(12,3) NOT NULL CHECK (quantity > 0),
    unit_price      NUMERIC(12,2) NOT NULL CHECK (unit_price >= 0),
    gst_rate        NUMERIC(5,2) NOT NULL DEFAULT 0,
    cgst_amount     NUMERIC(14,2) NOT NULL DEFAULT 0,
    sgst_amount     NUMERIC(14,2) NOT NULL DEFAULT 0,
    igst_amount     NUMERIC(14,2) NOT NULL DEFAULT 0,
    line_total      NUMERIC(14,2) NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_invoice_line_items_tenant_id ON invoice_line_items(tenant_id);
CREATE INDEX idx_invoice_line_items_invoice_id ON invoice_line_items(invoice_id);
CREATE INDEX idx_invoice_line_items_variant_id ON invoice_line_items(variant_id);

-- ----------------------------------------------------------------------------
-- stock_ledger: append-only audit trail of every stock movement.
-- Never UPDATE/DELETE rows here - corrections are new rows (e.g. ADJUSTMENT).
-- ----------------------------------------------------------------------------
CREATE TABLE stock_ledger (
    id                  UUID PRIMARY KEY,
    tenant_id           UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    variant_id          UUID NOT NULL REFERENCES product_variants(id),
    movement_type       VARCHAR(20) NOT NULL CHECK (
        movement_type IN ('PURCHASE', 'SALE', 'ADJUSTMENT', 'PURCHASE_RETURN', 'SALE_RETURN')
    ),
    quantity_change     NUMERIC(12,3) NOT NULL,   -- positive = stock in, negative = stock out
    balance_after       NUMERIC(14,3) NOT NULL,
    reference_type      VARCHAR(30),              -- e.g. 'PURCHASE_ENTRY', 'INVOICE'
    reference_id        UUID,
    remarks             TEXT,
    movement_date       DATE NOT NULL DEFAULT CURRENT_DATE,
    created_by          UUID REFERENCES users(id),
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_stock_ledger_tenant_variant_created
    ON stock_ledger(tenant_id, variant_id, created_at);
CREATE INDEX idx_stock_ledger_reference ON stock_ledger(reference_type, reference_id);
